// r1-mesh.js — baked Rabbit r1 model (generated from scene.usdz, do not edit)
// Layout: indexed triangles. pos Float32Array (xyz, model centered, max dim 2.0,
// +Y up, screen faces +Z). nrm Float32Array (xyz, normalized). uv Float32Array
// (top-left-origin V; use as-is with texImage2D(<img>) without UNPACK_FLIP_Y).
// idx Uint16Array. tex: 512px JPEG data URI (baseColor).
(function () {
  function b(s) {
    var d = atob(s), u = new Uint8Array(d.length);
    for (var i = 0; i < d.length; i++) u[i] = d.charCodeAt(i);
    return u;
  }
  var PS = 30000.0;
  var p16 = new Int16Array(b("").buffer);
  var n8 = new Int8Array(b("").buffer);
  var u16 = new Uint16Array(b("").buffer);
  var idx = new Uint16Array(b("").buffer);
  var n = p16.length / 3;
  var pos = new Float32Array(n * 3), nrm = new Float32Array(n * 3), uv = new Float32Array(n * 2);
  for (var i = 0; i < n * 3; i++) { pos[i] = p16[i] / PS; nrm[i] = n8[i] / 127; }
  for (var i = 0; i < n * 2; i++) uv[i] = u16[i] / 65535;
  window.R1_MESH = {
    pos: pos, nrm: nrm, uv: uv, idx: idx,
    vertCount: n, triCount: idx.length / 3,
    tex: "data:image/jpeg;base64,"
  };
})();
